import{_ as t,o as a,c as n,ak as i}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy documentation: start here","description":"Updated October 23, 2026. Beta: November 10, 2026 — Cryptita Plays community beta testing. Pre-final: November 21, 2026. You can start with the section for your role; this ind","frontmatter":{"title":"Chainy documentation: start here","description":"Updated October 23, 2026. Beta: November 10, 2026 — Cryptita Plays community beta testing. Pre-final: November 21, 2026. You can start with the section for your role; this ind","source":"docs/documentation-index.md","category":"Start here","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/documentation-index.md","filePath":"content/docs/documentation-index.md"}'),o={name:"content/docs/documentation-index.md"};function r(s,e,c,d,h,l){return a(),n("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-documentation-start-here">Chainy documentation: start here<a class="header-anchor" href="#chainy-documentation-start-here" aria-label="Link to this section">​</a></h1><p>Updated October 23, 2026. <strong>Beta: November 10, 2026 — Cryptita Plays community beta testing. Pre-final: November 21, 2026.</strong> You can start with the section for your role; this index points to the few documents needed for the next task.</p><h2 id="start-by-role">Start by role<a class="header-anchor" href="#start-by-role" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Role</th><th>Person</th><th>Start here</th></tr></thead><tbody><tr><td>Project and Design Lead</td><td>Sherwin Limosnero</td><td><a href="/Chainy-Docs/content/docs/project-baseline.html">Baseline and open decisions</a>, <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">task plan and Gantt</a>, <a href="/Chainy-Docs/content/docs/planning/quest-curriculum.html">quest curriculum</a>, <a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">school evidence</a></td></tr><tr><td>Tech Lead</td><td>Christian Jude Villaber</td><td><a href="/Chainy-Docs/content/docs/technical-design.html">Christian&#39;s adopted technical design</a>, <a href="/Chainy-Docs/content/docs/design/database-schema.html">database reference</a>, <a href="/Chainy-Docs/content/docs/hardware-validation.html">device checks</a></td></tr><tr><td>Art Lead</td><td>Luis Cabrido III</td><td><a href="/Chainy-Docs/content/docs/design/design-brief.html">visual brief</a>, <a href="/Chainy-Docs/content/docs/game-design.html">game design</a></td></tr><tr><td>Docs Lead</td><td>Sean Matthew Narvaez</td><td><a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">official manuscript outline</a>, <a href="/Chainy-Docs/content/docs/manuscript-working-draft.html">working draft</a>, <a href="/Chainy-Docs/content/docs/qa-evaluation.html">evaluation</a>, <a href="/Chainy-Docs/content/docs/user-guide.html">learner guide</a></td></tr><tr><td>UI</td><td>Miguel De Leon</td><td><a href="/Chainy-Docs/content/docs/design/app-flow.html">player screen flow</a>, <a href="/Chainy-Docs/content/docs/design/design-brief.html">visual brief</a></td></tr></tbody></table><p>All team members: <a href="/Chainy-Docs/content/docs/team-board-guide.html">board quick guide</a> and <a href="/Chainy-Docs/content/docs/team-delegation.html">role ownership</a>.</p><h2 id="where-to-make-changes">Where to make changes<a class="header-anchor" href="#where-to-make-changes" aria-label="Link to this section">​</a></h2><p>The <a href="/Chainy-Docs/content/docs/project-baseline.html">project baseline</a> is the decision record. <a href="/Chainy-Docs/content/docs/game-design.html">GDD v2</a> is the canonical gameplay source; <a href="/Chainy-Docs/content/docs/technical-design.html">Christian&#39;s technical design</a> supplies reusable architecture with the v2 integration addendum. Sherwin owns player-experience decisions; Christian owns code and implementation; Luis owns art production; Sean is the sole author of project documentation; Miguel owns game UI implementation. A card has one owner. Separate cards show handoffs between roles.</p><p>The <a href="https://owenlim225.github.io/Chainy-Docs/board/">interactive team board</a> holds current task status, dates, links, and named history. <a href="/Chainy-Docs/attachments/docs/backlog.json">backlog.json</a> is its publication snapshot. The <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">task plan</a> is the readable task/dependency plan. GitHub issues are queued copies; Trello is retired. The game remains offline and uses SQLite locally; the management board is separate.</p><h2 id="gdd-directory">GDD directory<a class="header-anchor" href="#gdd-directory" aria-label="Link to this section">​</a></h2><ul><li><a href="/Chainy-Docs/content/docs/game-design.html">Canonical GDD v2</a></li><li><a href="/Chainy-Docs/content/docs/gdd-template-editions.html">Current PDFs, all historical editions and v2 update notes</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/readme.html">Pre-adoption archive</a> — preserved history, not active requirements</li></ul><h2 id="full-reference">Full reference<a class="header-anchor" href="#full-reference" aria-label="Link to this section">​</a></h2><ul><li><a href="/Chainy-Docs/content/docs/requirements/product-requirements.html">Product acceptance checklist</a></li><li><a href="/Chainy-Docs/content/docs/requirements/technical-requirements.html">Technical acceptance checklist</a></li><li><a href="/Chainy-Docs/content/docs/offline-data-plan.html">Offline records and teacher collection</a></li><li><a href="/Chainy-Docs/content/docs/planning/implementation-plan.html">Implementation order</a></li><li><a href="/Chainy-Docs/content/docs/planning/quest-curriculum.html">Quest curriculum and source map</a></li><li><a href="/Chainy-Docs/content/docs/planning/agentic-parallel-execution-plan.html">Agentic parallel execution plan</a></li><li><a href="/Chainy-Docs/content/docs/mentors.html">Mentor guidance</a></li></ul><p>Earlier proposals are <a href="/Chainy-Docs/content/docs/archive/pre-2026-10-12/readme.html">preserved as history</a>, not active requirements. The supplied design is retained under <a href="/Chainy-Docs/content/docs/archive/source-material/technical-design-christian-2026-10-12.html">source material</a>; its assignment prompts are evidence, not instructions to the assistant.</p></div>',1)])])}const p=t(o,[["render",r]]);export{u as __pageData,p as default};
